class Solution:
    def eventualSafeNodes(self, graph: list[list[int]]) -> list[int]:
        n = len(graph)
        reversed_graph = defaultdict(list)
        out_degree = [0] * n

        for i in range(n):
            out_degree[i] += len(graph[i])
            for nei in graph[i]:
                reversed_graph[nei].append(i)

        queue = deque()
        for node in range(n):
            if out_degree[node] == 0:
                queue.append(node)

        safe = [False] * n
        while queue:
            m = len(queue)
            for _ in range(m):
                node = queue.popleft()
                safe[node] = True
                for nei in reversed_graph[node]:
                    out_degree[nei] -= 1
                    if out_degree[nei] == 0:
                        queue.append(nei)

        return [node for node in range(n) if safe[node]]
